The Terraform configuration below uses the AWS provider and defines a `data "aws_ami"` lookup to retrieve the latest Amazon Linux 2 AMI published by Amazon. It outputs the AMI ID so it can be used by other Terraform resources such as EC2 instances.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to search for the latest Amazon Linux 2 AMI."
  type        = string
  default     = "us-east-1"
}

data "aws_ami" "latest_amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name = "name"
    values = [
      "amzn2-ami-hvm-*-x86_64-gp2"
    ]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }

  filter {
    name   = "state"
    values = ["available"]
  }
}

output "latest_amazon_linux_2_ami_id" {
  description = "The AMI ID of the latest Amazon Linux 2 AMI."
  value       = data.aws_ami.latest_a
